function romanValue(s: string): number {
  const one: Record<string, number> = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  const pair: Record<string, number> = { IV: 4, IX: 9, XL: 40, XC: 90, CD: 400, CM: 900 };
  let total = 0, i = 0;
  while (i < s.length) {
    const two = s.slice(i, i + 2);
    if (two in pair) {
      total += pair[two];
      i += 2;
    } else {
      total += one[s[i]];
      i++;
    }
  }
  return total;
}

