function romanValue(s: string): number {
  const val: Record<string, number> = { I: 1, V: 5, X: 10, L: 50, C: 100, D: 500, M: 1000 };
  let total = 0;
  for (let i = 0; i < s.length; i++) {
    const v = val[s[i]];
    if (i + 1 < s.length && val[s[i + 1]] > v) total -= v;
    else total += v;
  }
  return total;
}

